@router.get("/departments/{dept_id}/budget-aggregate")
async def get_department_budget_aggregate(
    dept_id: str,
    current_user: User = Depends(get_current_user)
):
    if current_user.department_code != dept_id and not current_user.is_finance_auditor:
        raise HTTPException(status_code=403, detail="Forbidden: access to department financial aggregates denied")

    pipeline = [
        {"$match": {"department_code": dept_id}},
        {"$group": {"_id": "$expense_category", "total_spend": {"$sum": "$amount"}, "count": {"$sum": 1}}},
        {"$sort": {"total_spend": -1}}
    ]
    results = await ExpenseRecord.aggregate(pipeline).to_list()
    return {"department": dept_id, "breakdown": results}
